-- InnaOpcja.pl -- seed: 127 gier (statyczne dane, bez live-cen), zastepuje telefony/telewizory jako jedyna aktywna kategoria.


-- Stare kategorie archiwizowane, nie kasowane - dane zostaja w bazie, ale znikaja z live strony (wszystkie zapytania filtruja status=published).
UPDATE products SET status = 'draft', updated_at = now() WHERE category_id IN (SELECT id FROM categories WHERE slug IN ('telefony', 'telewizory'));

