INSERT INTO products (category_id, name, slug, normalized_name, brand, brand_recognition, verdict, score, summary, pros, cons, specs, price_tier, release_year, status) VALUES
((SELECT id FROM categories WHERE slug = 'gry'), 'Wiedźmin 3: Dziki Gon', 'wiedzmin-3-dziki-gon', 'wiedzmin 3 dziki gon', 'CD Projekt Red', 'mainstream', 'Wydana przez CD Projekt Red, Wiedźmin 3: Dziki Gon to rpg akcji na PC, PlayStation, Xbox i Switch. Największym atutem jest tu fabuła i klimat.', 6.7, 'To czysto solowe doświadczenie - najlepsze we własnym tempie, bez potrzeby kogoś do grania. Typowa sesja to długie, wciągające sesje warte wygospodarowania wieczoru. Szeroka dostępność platformowa - duża szansa, że zagrasz na tym, co już masz.', '["Historia, która naprawdę wciąga od początku do końca","Dopracowana, satysfakcjonująca mechanika rozgrywki","Dostępna na PC, PlayStation, Xbox i Switch - duży wybór sprzętu do grania"]'::jsonb, '["Brak jakiegokolwiek trybu wieloosobowego - czysto solowe doświadczenie","Długie sesje - trudno wcisnąć w krótką przerwę","Warto sprawdzić krótki fragment rozgrywki przed zakupem, żeby ocenić klimat na własną rękę"]'::jsonb, '{"platformy":["PC","PlayStation","Xbox","Switch"],"tryb":"solo","gatunek":"RPG akcji","fabula_score":5,"rozgrywka_score":4,"spoleczny_score":1,"sesja_minuty":90}'::jsonb, 'sredni', 2015, 'published'),
((SELECT id FROM categories WHERE slug = 'gry'), 'Cyberpunk 2077', 'cyberpunk-2077', 'cyberpunk 2077', 'CD Projekt Red', 'mainstream', 'Cyberpunk 2077 to rpg akcji dostępna na PC, PlayStation i Xbox. Największym atutem jest tu fabuła i klimat.', 6.7, 'To czysto solowe doświadczenie - najlepsze we własnym tempie, bez potrzeby kogoś do grania. Typowa sesja to długie, wciągające sesje warte wygospodarowania wieczoru.', '["Historia, która naprawdę wciąga od początku do końca","Dopracowana, satysfakcjonująca mechanika rozgrywki","Znane, sprawdzone studio stojące za produkcją (CD Projekt Red)"]'::jsonb, '["Brak jakiegokolwiek trybu wieloosobowego - czysto solowe doświadczenie","Warto sprawdzić krótki fragment rozgrywki przed zakupem, żeby ocenić klimat na własną rękę"]'::jsonb, '{"platformy":["PC","PlayStation","Xbox"],"tryb":"solo","gatunek":"RPG akcji","fabula_score":5,"rozgrywka_score":4,"spoleczny_score":1,"sesja_minuty":75}'::jsonb, 'sredni', 2020, 'published'),
((SELECT id FROM categories WHERE slug = 'gry'), 'Red Dead Redemption 2', 'red-dead-redemption-2', 'red dead redemption 2', 'Rockstar Games', 'mainstream', 'Wydana przez Rockstar Games, Red Dead Redemption 2 to akcja/przygoda (otwarty świat) na PC, PlayStation i Xbox. Gra stawia przede wszystkim na historię i narrację.', 6.7, 'Czysto solowe doświadczenie - najlepsze we własnym tempie, bez potrzeby kogoś do grania. Pod względem rytmu rozgrywki to długie, wciągające sesje warte wygospodarowania wieczoru.', '["Mocna, zapadająca w pamięć fabuła i klimat","Gameplay, który sam w sobie jest głównym powodem, żeby zagrać","Znane, sprawdzone studio stojące za produkcją (Rockstar Games)"]'::jsonb, '["Brak jakiegokolwiek trybu wieloosobowego - czysto solowe doświadczenie","Długie sesje - trudno wcisnąć w krótką przerwę","Warto sprawdzić krótki fragment rozgrywki przed zakupem, żeby ocenić klimat na własną rękę"]'::jsonb, '{"platformy":["PC","PlayStation","Xbox"],"tryb":"solo","gatunek":"Akcja/przygoda (otwarty świat)","fabula_score":5,"rozgrywka_score":4,"spoleczny_score":1,"sesja_minuty":90}'::jsonb, 'sredni', 2018, 'published'),
((SELECT id FROM categories WHERE slug = 'gry'), 'Grand Theft Auto V', 'grand-theft-auto-v', 'grand theft auto v', 'Rockstar Games', 'mainstream', 'Wydana przez Rockstar Games, Grand Theft Auto V to akcja (otwarty świat) na PC, PlayStation i Xbox. Gra stawia przede wszystkim na historię i narrację.', 7.3, 'Da się grać solo, ale naprawdę rozkwita w towarzystwie albo online. Pod względem rytmu rozgrywki to długie, wciągające sesje warte wygospodarowania wieczoru. Bardzo przystępna cena sprawia, że warto dać jej szansę bez większego ryzyka.', '["Mocna, zapadająca w pamięć fabuła i klimat","Gameplay, który sam w sobie jest głównym powodem, żeby zagrać","Opcja grania ze znajomymi, gdy akurat masz na to ochotę"]'::jsonb, '["To nie jest gra stawiająca na grę wieloosobową - inne aspekty są tu ważniejsze","Warto sprawdzić krótki fragment rozgrywki przed zakupem, żeby ocenić klimat na własną rękę"]'::jsonb, '{"platformy":["PC","PlayStation","Xbox"],"tryb":"oba","gatunek":"Akcja (otwarty świat)","fabula_score":4,"rozgrywka_score":4,"spoleczny_score":3,"sesja_minuty":60}'::jsonb, 'budzetowy', 2013, 'published'),
